def handle(query, state):
    import shlex

    logfile = (query.get('log') or [''])[0].strip()
    lines_param = (query.get('lines') or ['20'])[0].strip()

    if not logfile:
        return 400, {'Content-Type': 'text/plain'}, 'Missing required parameter: log'

    try:
        n = int(lines_param)
    except ValueError:
        n = 20
    n = max(1, min(n, 200))

    # The server naively builds a shell command string from user input
    # and executes it through a simulated shell interpreter.
    # Injection point: logfile is interpolated without sanitization.
    cmd_string = 'tail -n {} {}'.format(n, logfile)

    files = state.get('files', {})
    env = state.get('env', {})
    output_parts = []

    # Simulated shell: split on ';' for command chaining
    for raw_cmd in cmd_string.split(';'):
        tokens = shlex.split(raw_cmd.strip()) if raw_cmd.strip() else []
        if not tokens:
            continue
        verb = tokens[0]

        if verb == 'tail':
            # tail [-n <count>] <path>
            path = None
            count = 10
            i = 1
            while i < len(tokens):
                if tokens[i] == '-n' and i + 1 < len(tokens):
                    try:
                        count = int(tokens[i + 1])
                    except ValueError:
                        pass
                    i += 2
                else:
                    path = tokens[i]
                    i += 1
            if path is None:
                output_parts.append('tail: missing file operand')
                continue
            content = files.get(path)
            if content is None:
                output_parts.append('tail: {}: No such file or directory'.format(path))
            else:
                log_lines = content.splitlines()
                output_parts.append('\n'.join(log_lines[-count:]))

        elif verb == 'cat':
            if len(tokens) < 2:
                output_parts.append('cat: missing operand')
                continue
            path = tokens[1]
            content = files.get(path)
            if content is None:
                output_parts.append('cat: {}: No such file or directory'.format(path))
            else:
                output_parts.append(content)

        elif verb == 'ls':
            target = tokens[1] if len(tokens) > 1 else '/var/log'
            matches = [k for k in files if k.startswith(target)]
            if matches:
                output_parts.append('\n'.join(sorted(matches)))
            else:
                output_parts.append('ls: {}: No such file or directory'.format(target))

        elif verb == 'printenv':
            if len(tokens) > 1:
                key = tokens[1]
                output_parts.append(env.get(key, ''))
            else:
                output_parts.append('\n'.join('{}={}'.format(k, v) for k, v in env.items()))

        elif verb == 'id':
            output_parts.append('uid=1000(logviewer) gid=1000(logviewer) groups=1000(logviewer)')

        elif verb == 'echo':
            output_parts.append(' '.join(tokens[1:]))

        else:
            output_parts.append('{}: command not found'.format(verb))

    body = '\n'.join(output_parts)
    return 200, {'Content-Type': 'text/plain'}, body
